impl Solution {
    pub fn max_k_segments_sum(nums: Vec<i64>, m: usize, k: usize) -> i128 {
        let n = nums.len();
        let mut dp = vec![vec![-1i128; n + 1]; k + 1];
        dp[0][0] = 0;

        for i in 1..=k {
            let mut prefix = vec![0i128; n + 1];
            for j in 0..n {
                prefix[j + 1] = prefix[j] + nums[j] as i128;
            }

            for j in 0..=n {
                if dp[i - 1][j] == -1 {
                    continue;
                }
                for l in j..n {
                    let r = l + m;
                    if r > n {
                        break;
                    }
                    let current_sum = prefix[r] - prefix[l];
                    let new_sum = dp[i - 1][j] + current_sum;
                    if new_sum > dp[i][r] {
                        dp[i][r] = new_sum;
                    }
                }
            }
        }

        *dp[k].iter().max().unwrap()
    }
}
